#include <Servo.h>                                // Importar librería para controlar el servo

#include "BluetoothSerial.h"


Servo servoLook;                                  // Crear un objeto para controlar el servo

BluetoothSerial SerialBT;                         // Objeto para controlar la comunicación Bluetooth

bool SwitchONOFF;                                 // Valor a usarse en la comunicación Bluetooth

byte trig = 27;                                   // Asignar pines al sensor ultrasónico

byte echo = 14;

byte maxDist = 150;                               // Distancia máxima de sensado (objetos más lejanos se ignoran)

byte stopDist = 50;                               // Distancia mínima para detenerse en cm

float timeOut = 2 * (maxDist + 10) / 100 / 340 * 1000000; // Tiempo máximo para esperar una señal de retorno


void setup() {

  SwitchONOFF = 0;

  SerialBT.begin("Carro");                        // Nombre del ESP32 en Bluetooth (se puede cambiar)

  pinMode(32, OUTPUT);                            // Motor izquierdo delantero

  pinMode(23, OUTPUT);                            // Motor izquierdo trasero

  pinMode(25, OUTPUT);                            // Motor derecho delantero

  pinMode(26, OUTPUT);                            // Motor derecho trasero

  servoLook.attach(12);                           // Asignar pin al servo

  pinMode(trig, OUTPUT);

  pinMode(echo, INPUT);

}


void loop() {

  if (SerialBT.available()) {                     // Verificar si hay datos disponibles del Bluetooth

    char received = (char)SerialBT.read();

    if (received == 'A') {                        // Leer el valor enviado por Bluetooth

      SwitchONOFF = 1;

    }

    if (received == 'B') {                        // Leer el valor enviado por Bluetooth

      SwitchONOFF = 0;

    }

  }


  if (SwitchONOFF == HIGH) {                      // Si el valor enviado por Bluetooth es 1, el carro funciona normalmente; si es 0, se queda suspendido

    servoLook.write(90);                          // Ajustar el servo para mirar al frente

    delay(750);

    int distance = getDistance();                 // Verificar que no haya objetos adelante

    if (distance >= stopDist) {                   // Si no hay objetos dentro de la distancia de parada, avanzar

      moveForward();

    }

    while (distance >= stopDist) {                // Seguir verificando la distancia del objeto hasta que esté dentro de la distancia mínima de parada

      distance = getDistance();

      delay(250);

    }

    stopMove();                                   // Detener los motores

    int turnDir = checkDirection();               // Verificar las distancias a la izquierda y a la derecha y obtener la instrucción de giro

    Serial.print(turnDir);

    switch (turnDir) {                            // Girar a la izquierda, dar la vuelta o girar a la derecha dependiendo de la instrucción

      case 0:                                     // Girar a la izquierda

        turnLeft(700);

        break;

      case 1:                                     // Dar la vuelta

        turnLeft(1500);

        break;

      case 2:                                     // Girar a la derecha

        turnRight(700);

        break;

    }

  }

}


void moveForward() {                              // Configurar todos los motores para avanzar

  digitalWrite(32, HIGH);

  digitalWrite(25, HIGH);

}


void stopMove() {                                 // Configurar todos los motores para detenerse

  digitalWrite(32, LOW);

  digitalWrite(23, LOW);

  digitalWrite(25, LOW);

  digitalWrite(26, LOW);

}


void turnLeft(int duration) {                     // Configurar motores para girar a la izquierda durante la duración especificada y luego detenerse

  digitalWrite(32, HIGH);

  delay(duration);

  digitalWrite(32, LOW);

}


void turnRight(int duration) {                    // Configurar motores para girar a la derecha durante la duración especificada y luego detenerse

  digitalWrite(25, HIGH);

  delay(duration);

  digitalWrite(25, LOW);

}


int getDistance() {                               // Medir la distancia a un objeto

  unsigned long pulseTime;                        // Crear una variable para almacenar el tiempo de viaje del pulso

  int distance;                                   // Crear una variable para almacenar la distancia calculada

  digitalWrite(trig, HIGH);                       // Generar un pulso de 10 microsegundos

  delayMicroseconds(10);

  digitalWrite(trig, LOW);

  pulseTime = pulseIn(echo, HIGH, timeOut);       // Medir el tiempo para que el pulso regrese

  distance = (float)pulseTime * 340 / 2 / 10000;  // Calcular la distancia del objeto basada en el tiempo del pulso

  return distance;

}


int checkDirection() {                            // Verificar las direcciones izquierda y derecha y decidir hacia dónde girar

  int distances[2] ={0, 0};                      // Distancias izquierda y derecha

  int turnDir = 1;                                // Dirección para girar: 0 izquierda, 1 reversa, 2 derecha

  servoLook.write(180);                           // Girar el servo para mirar a la izquierda

  delay(500);

  distances[0] =getDistance();                   // Obtener la distancia del objeto a la izquierda

  servoLook.write(0);                             // Girar el servo para mirar a la derecha

  delay(1000);

  distances[1] = getDistance();                   // Obtener la distancia del objeto a la derecha

  if (distances[0] >= 200 && distances[1] >= 200) // Si ambas direcciones están despejadas, girar a la izquierda

    turnDir = 0;

  else if (distances[0] <= stopDist && distances[1] <= stopDist) // Si ambas direcciones están bloqueadas, dar la vuelta

    turnDir = 1;

  else if (distances[0] >= distances[1])          // Si la izquierda tiene más espacio, girar a la izquierda

    turnDir = 0;

  else if (distances[0] < distances[1])           // Si la derecha tiene más espacio, girar a la derecha

    turnDir = 2;

  return turnDir;

}




