#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;
// Define a structure to represent a student with name, score, and grade
struct Student {
    string name;
    int score;
    char grade;
};
// Function to determine the grade based on the percentage
char determineGrade(double percentage) {
    // Assign grades based on percentage ranges
    if (percentage >= 95) return 'A';
    else if (percentage >= 80) return 'B';
    else if (percentage >= 65) return 'C';
    else if (percentage >= 50) return 'D';
    else return 'E'; // If percentage is below 60
}
// Merge two sorted subarrays into a single sorted array
void merge(vector<Student>& students, int left, int mid, int right) {
    // Calculate sizes of two subarrays to be merged
    int n1 = mid - left + 1;
    int n2 = right - mid;

    // Create temporary vectors to hold the two subarrays
    vector<Student> L(n1);
    vector<Student> R(n2);

    // Copy data to temporary vectors L[] and R[]
    for (int i = 0; i < n1; i++)
        L[i] = students[left + i];
    for (int j = 0; j < n2; j++)
        R[j] = students[mid + 1 + j];

    // Merge the two temporary vectors back into students vector
    int i = 0, j = 0, k = left;

    // Merge the two subarrays back into the original array in sorted order
    while (i < n1 && j < n2) {
        if (L[i].score > R[j].score) {
            students[k] = L[i];
            i++;
        } else {
            students[k] = R[j];
            j++;
        }
        k++;
    }
    // Copy any remaining elements of L[] if there are any
    while (i < n1) {
        students[k] = L[i];
        i++;
        k++;
    }
    // Copy any remaining elements of R[] if there are any
    while (j < n2) {
        students[k] = R[j];
        j++;
        k++;
    }
}
// Recursive function to perform merge sort on the students vector
void mergeSort(vector<Student>& students, int left, int right) {
    // Check if there are more than one element to sort
    if (left < right) {
        // Calculate middle index
        int mid = left + (right - left) / 2;

        // Recursive calls for left and right subarrays
        mergeSort(students, left, mid);
        mergeSort(students, mid + 1, right);

        // Merge the sorted subarrays
        merge(students, left, mid, right);
    }
}
// Main function to input student data, calculate grades, and display sorted results
int main() {
    vector<Student> students; // Vector to store student data
    int n; // Number of students
    double totalMarks; // Maximum total marks for grading
cout<< "The ranking system of an assessable task for students in Primary Schools of PNG.\n\n";
    // Input the maximum score for grading
    cout << "Enter maximum score: ";
    cin >> totalMarks;

    // Input the number of students
    cout << "Enter the number of students: ";
    cin >> n;

    // Input each student's name and score, calculate grade, and store in the vector
    cout << "\nEnter the student's name and the score:\n";
    for (int i = 0; i < n; i++) {
        Student student;
        cout << i + 1 << ". Name: ";
        cin >> student.name;
        cout << "   Score: ";
        cin >> student.score;

        // Validate the score and calculate grade
        if (student.score < 0 || student.score > totalMarks) {
            cout << "Score must be between 0 and " << totalMarks << ". Please enter correctly.\n";
            return 1; // Exit if score is invalid
        }

        // Calculate the percentage and determine the grade
        double percentage = static_cast<double>(student.score) / totalMarks * 100;
        student.grade = determineGrade(percentage);

        // Add the student to the vector
        students.push_back(student);
    }

    // Sort the students based on score in descending order using merge sort
    mergeSort(students, 0, n - 1);

    // Display the students sorted by score along with their names, scores, and grades
    cout << "\nStudents are sorted by their scores and grade in descending order:\n";
    for (const Student& student : students) {
        cout << student.name << ": Score: " << student.score<< "/" <<totalMarks  << ", Grade: " << student.grade << "\n";
    }

    return 0; // Exit the program successfully
}

